package main
import("debug/dwarf";"debug/elf";"encoding/json";"fmt";"os";"strings")
func main(){f,e:=elf.Open(os.Args[1]);if e!=nil{panic(e)};defer f.Close();d,e:=f.DWARF();if e!=nil{panic(e)};r:=d.Reader();out:=map[string]any{};for{entry,e:=r.Next();if e!=nil{panic(e)};if entry==nil{break};if entry.Tag!=dwarf.TagStructType{continue};n,_:=entry.Val(dwarf.AttrName).(string);if !strings.HasPrefix(n,"github.com/microsoft/typescript-go/internal/checker."){continue};short:=strings.TrimPrefix(n,"github.com/microsoft/typescript-go/internal/checker.");switch short{case "Type","TypeBase","IntrinsicType","LiteralType","UniqueESSymbolType","ConstrainedType","StructuredType","ObjectType","TypeReference","InterfaceType","TupleType","InstantiationExpressionType","MappedType","ReverseMappedType","EvolvingArrayType","UnionOrIntersectionType","UnionType","IntersectionType","TypeParameter","IndexType","IndexedAccessType","TemplateLiteralType","StringMappingType","SubstitutionType","ConditionalType":default:continue};typ,e:=d.Type(entry.Offset);if e!=nil{panic(e)};s,ok:=typ.(*dwarf.StructType);if !ok{continue};fields:=[]map[string]any{};for _,field:=range s.Field {if short=="Type"||len(fields)==0{fields=append(fields,map[string]any{"name":field.Name,"offset":field.ByteOffset,"size":field.Type.Size(),"type":field.Type.String()})}};out[short]=map[string]any{"size":s.Size(),"fields":fields}};data,_:=json.MarshalIndent(out,"","  ");fmt.Println(string(data))}
